#include "Renderer/Splat/LOD/SplatLODSelector.h"
#include "Renderer/Splat/LOD/SplatSceneFormat.h"
#include <algorithm>
#include <cmath>
#include <filesystem>
#include <fstream>
#include <iostream>
#include <sstream>
#include <stdexcept>
using namespace MonsterRender::Splat;
namespace fs=std::filesystem;
static void Check(bool b,const std::string& e){if(!b)throw std::runtime_error(e);}
static std::vector<uint8_t> Read(const fs::path& p){std::ifstream f(p,std::ios::binary);Check(bool(f),"cannot read "+p.string());return {std::istreambuf_iterator<char>(f),{}};}
static std::vector<float> Array(const std::string& json,const std::string& name,unsigned count){auto pos=json.find('"'+name+'"');Check(pos!=std::string::npos,"metadata field missing "+name);pos=json.find('[',pos);auto end=json.find(']',pos);Check(pos!=std::string::npos&&end!=std::string::npos,"metadata array malformed");std::stringstream ss(json.substr(pos+1,end-pos-1));std::vector<float> values;std::string item;while(std::getline(ss,item,',')){size_t used=0;float value=std::stof(item,&used);Check(std::isfinite(value)&&used==item.size(),"nonfinite/trailing metadata");values.push_back(value);}Check(values.size()==count,"metadata field count");return values;}
// Independent six-plane frustum/AABB oracle; no selector support-area estimate.
static bool Visible(const FSplatBounds& b,const FSplatLODView& v){double vp[4][4]{};for(unsigned r=0;r<4;++r)for(unsigned c=0;c<4;++c)for(unsigned k=0;k<4;++k)vp[r][c]+=double(v.projection[k*4+r])*v.view[c*4+k];for(unsigned p=0;p<6;++p){double plane[4];for(unsigned c=0;c<4;++c)plane[c]=p<4?vp[3][c]+(p%2?-1:1)*vp[p/2][c]:p==4?vp[2][c]:vp[3][c]-vp[2][c];double maximum=plane[3];for(unsigned k=0;k<3;++k)maximum+=plane[k]*(plane[k]>=0?b.max[k]:b.min[k]);if(maximum<0)return false;}return true;}
int main(int argc,char** argv){try{Check(argc==4,"usage: audit scene.mgs capture.json report.json");FSplatSceneManifest m;std::string e;Check(FSplatSceneFormat::LoadManifest(argv[1],m,e),e);auto bytes=Read(argv[2]);std::string json(bytes.begin(),bytes.end());FSplatLODView v;auto view=Array(json,"view",16),proj=Array(json,"projection",16),position=Array(json,"cameraPosition",3);std::copy(view.begin(),view.end(),v.view);std::copy(proj.begin(),proj.end(),v.projection);std::copy(position.begin(),position.end(),v.cameraPosition);v.width=1920;v.height=1080;FSplatResidencySnapshot resident;resident.sceneGeneration=1;uint32_t offset=0;for(const auto& page:m.pages){resident.pages.push_back({page.id,offset,page.gaussianCount,1,true});offset+=page.gaussianCount;}FSplatLODSettings settings;settings.activeBudget=m.sourceCount;settings.sourceBudget=offset;settings.sortBudget=64000000;FSplatLODSelector selector;auto cut=selector.Select(m,v,settings,resident);Check(!cut.degraded&&!cut.selectedNodeIds.empty(),"audit selector not complete/settled");std::vector<uint32_t> parent(m.nodes.size(),SplatInvalidId);for(unsigned id=0;id<m.nodes.size();++id)for(auto child:m.nodes[id].children)parent[child]=id;std::vector<bool> selected(m.nodes.size());for(auto id:cut.selectedNodeIds){Check(!selected[id],"duplicate selected node");selected[id]=true;}for(auto id:cut.selectedNodeIds)for(auto ancestor=parent[id];ancestor!=SplatInvalidId;ancestor=parent[ancestor])Check(!selected[ancestor],"ancestor/descendant contribution duplication");unsigned visibleLeaves=0,missing=0;for(unsigned id=0;id<m.nodes.size();++id)if(m.nodes[id].children.empty()&&Visible(m.nodes[id].bounds,v)){++visibleLeaves;auto ancestor=id;while(ancestor!=SplatInvalidId&&!selected[ancestor])ancestor=parent[ancestor];if(ancestor==SplatInvalidId)++missing;}Check(missing==0,"independent frustum-visible leaf coverage missing");std::vector<bool> originalSeen(m.sourceCount);uint64_t leafRecords=0,proxyRecords=0;unsigned leafNodes=0,proxyNodes=0;const auto directory=fs::path(argv[1]).parent_path();for(auto id:cut.selectedNodeIds){bool leaf=m.nodes[id].children.empty();if(leaf)++leafNodes;else ++proxyNodes;for(auto page:m.nodes[id].pageIds){std::vector<FSplatGaussian> gs;Check(FSplatSceneFormat::DecodePage(m,page,Read(directory/m.pages[page].relativePath),gs,e),e);for(const auto& g:gs){if(leaf){Check(g.originalId<m.sourceCount&&!originalSeen[g.originalId],"leaf original identity missing/duplicate");originalSeen[g.originalId]=true;++leafRecords;}else ++proxyRecords;}}}Check(leafRecords+proxyRecords==cut.activeCount,"decoded active count differs from actual cut");std::ofstream out(argv[3]);out<<"{\"status\":\"PASS\",\"sourceCount\":"<<m.sourceCount<<",\"selectedLeafNodes\":"<<leafNodes<<",\"selectedProxyNodes\":"<<proxyNodes<<",\"leafOriginalRecords\":"<<leafRecords<<",\"proxyRecords\":"<<proxyRecords<<",\"activeCount\":"<<cut.activeCount<<",\"independentlyVisibleLeaves\":"<<visibleLeaves<<",\"missingVisibleLeaves\":"<<missing<<",\"uniqueLeafIdentities\":true,\"selectedNodeIds\":[";for(unsigned i=0;i<cut.selectedNodeIds.size();++i){if(i)out<<',';out<<cut.selectedNodeIds[i];}out<<"]}\n";out.close();Check(bool(out),"audit artifact write");std::cout<<"PASS T03 T06 real cut independent coverage/identity audit leafRecords="<<leafRecords<<" proxyRecords="<<proxyRecords<<"\n";return 0;}catch(const std::exception& e){std::cerr<<"FAIL real cut audit: "<<e.what()<<'\n';return 1;}}
